records.logicalInterface:
lemma Advance(a: nat,e: nat,k: nat,aa: nat,t: nat)
    requires k > 0 && e+k <= 127
    requires aa == a/B.Power(2*e) && t == B.Power(e)
    requires 1 <= aa < B.Power(4*k)
    ensures var next := e+(if aa >= B.Power(2*k) then k else 0);
            1 <= a/B.Power(2*next) < B.Power(2*k)
    ensures var next := e+(if aa >= B.Power(2*k) then k else 0);
            (if aa >= B.Power(2*k) then aa/B.Power(2*k) else aa) == a/B.Power(2*next)
    ensures var next := e+(if aa >= B.Power(2*k) then k else 0);
            B.Power(next) == t*(if aa >= B.Power(2*k) then B.Power(k) else 1)

method Inverse(base: nat,modulus: nat) returns (out: M.Outcome)
    requires base < B.Word && modulus < B.Word
    ensures out == (if modulus == 0 then M.Panic(18)
                    else if modulus > 1 && E.Gcd(modulus,base%modulus) != 1 then M.MissingInverse(base,modulus)
                    else M.Value(V.Spec(base,modulus)))
    ensures out.Value? ==> 0 <= out.result < B.Word

lemma TailState(r: nat,a: nat,n: nat,m: nat)
    requires m > 0
    ensures var nextR := if n%2 == 1 then Multiply(r,a)%m else r;
            var nextN := n/2;
            var nextA := if nextN > 0 then Multiply(a,a)%m else a;
            Multiply(nextR,Power(nextA,nextN))%m == Multiply(r,Power(a,n))%m
